INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(221981, 13117, 772, '<td valign="top">Excellent shot... those clouds look great... I love to get the opportunity to catch those ''puffy'' white clouds like that :) - setzler</td>', 'Excellent shot... those clouds look great... I love to get the opportunity to catch those ''puffy'' white clouds like that :) - setzler', '2003-02-24 00:06:05.000000', NULL, 1),
(221982, 12840, 6855, '<td valign="top">Very cool camera!  Where on earth did you find it????</td>', 'Very cool camera!  Where on earth did you find it????', '2003-02-24 00:06:29.000000', NULL, 1),
(221983, 12922, 772, '<td valign="top">This is definitely an interesting subject, but I think the shadows on the face of the building make it look a bit odd.  Maybe a different time of day would create a better shot overall... nice work though :) - setzler</td>', 'This is definitely an interesting subject, but I think the shadows on the face of the building make it look a bit odd.  Maybe a different time of day would create a better shot overall... nice work though :) - setzler', '2003-02-24 00:07:06.000000', NULL, 1),
(221984, 13018, 6855, '<td valign="top">This is a really cool photo, especially with the people reflecting in the dial.</td>', 'This is a really cool photo, especially with the people reflecting in the dial.', '2003-02-24 00:07:32.000000', NULL, 1),
(221985, 12909, 772, '<td valign="top">I think that the road leading up to this barn is a nice element.. I also think you made a good choice to photograph from this angle instead of a straight on view... - setzler</td>', 'I think that the road leading up to this barn is a nice element.. I also think you made a good choice to photograph from this angle instead of a straight on view... - setzler', '2003-02-24 00:08:48.000000', NULL, 1),
(221986, 13062, 6855, '<td valign="top">This is a really neat photo - how did you get the green water effect, or was it truly that way?</td>', 'This is a really neat photo - how did you get the green water effect, or was it truly that way?', '2003-02-24 00:08:53.000000', NULL, 1),
(221987, 13082, 6855, '<td valign="top">A perfect 10 - gorgeous photo!</td>', 'A perfect 10 - gorgeous photo!', '2003-02-24 00:09:35.000000', NULL, 1),
(221988, 13061, 772, '<td valign="top">This looks like a good photojournalism shot :)  Thats a LOT of snow :)  good catch - setzler</td>', 'This looks like a good photojournalism shot :)  Thats a LOT of snow :)  good catch - setzler', '2003-02-24 00:09:40.000000', NULL, 1),
(221990, 13045, 6855, '<td valign="top">Cute title, good photo, well done!</td>', 'Cute title, good photo, well done!', '2003-02-24 00:10:30.000000', NULL, 1),
(221991, 13038, 772, '<td valign="top">i like the way the sunlight is diving into this photo between the buildings.. nice work :) - setzler</td>', 'i like the way the sunlight is diving into this photo between the buildings.. nice work :) - setzler', '2003-02-24 00:10:54.000000', NULL, 1),
(221992, 13000, 6855, '<td valign="top">I love how the weak link is in the hot spot of the photo. Very creative and nicely done.</td>', 'I love how the weak link is in the hot spot of the photo. Very creative and nicely done.', '2003-02-24 00:11:29.000000', NULL, 1),
(221993, 12934, 772, '<td valign="top">excellent work with the dark background and a nice composition as well :) - setzler</td>', 'excellent work with the dark background and a nice composition as well :) - setzler', '2003-02-24 00:11:31.000000', NULL, 1),
(221996, 13089, 6855, '<td valign="top">Cool shoes!  Would make a great Doc Marten ad!</td>', 'Cool shoes!  Would make a great Doc Marten ad!', '2003-02-24 00:12:21.000000', NULL, 1),
(221998, 12854, 772, '<td valign="top">excellent work with shallow depth of field... the detail here is excellent :) - setzler</td>', 'excellent work with shallow depth of field... the detail here is excellent :) - setzler', '2003-02-24 00:12:50.000000', NULL, 1),
(221999, 12971, 6855, '<td valign="top">Haven''t we seen enough snow??? LOL, just kidding - awesome shot!</td>', 'Haven''t we seen enough snow??? LOL, just kidding - awesome shot!', '2003-02-24 00:13:04.000000', NULL, 1),
(222000, 12987, 4159, '<td valign="top">This is a nice portrait.  I''m not sure if it would be stuck in a photo frame, though - they always seem to smile in photo frames.  Also, the lighting on her hair gives her kind of an alien feel.  Still, good shot.</td>', 'This is a nice portrait.  I''m not sure if it would be stuck in a photo frame, though - they always seem to smile in photo frames.  Also, the lighting on her hair gives her kind of an alien feel.  Still, good shot.', '2003-02-24 00:13:18.000000', NULL, 1),
(222001, 13071, 4159, '<td valign="top">I like the DOF here, but I wish the pine cones were a bit brighter, as they''re the focal point.</td>', 'I like the DOF here, but I wish the pine cones were a bit brighter, as they''re the focal point.', '2003-02-24 00:14:07.000000', NULL, 1),
(222002, 12953, 6855, '<td valign="top">The colors are distracting for some reason???  It''s a great photo, but for some reason, her features don''t seem to match her clothing.  Your lighting is very good though!</td>', 'The colors are distracting for some reason???  It''s a great photo, but for some reason, her features don''t seem to match her clothing.  Your lighting is very good though!', '2003-02-24 00:14:10.000000', NULL, 1),
(222004, 13089, 4159, '<td valign="top">The colors and DOF here are very nice, and I suppose they just might hang this in a shoe store.  Not sure about the off-white background.</td>', 'The colors and DOF here are very nice, and I suppose they just might hang this in a shoe store.  Not sure about the off-white background.', '2003-02-24 00:14:47.000000', NULL, 1),
(222005, 12940, 6855, '<td valign="top">Absolutely AWESOME effect!  This is a once-in-a-lifetime shot!</td>', 'Absolutely AWESOME effect!  This is a once-in-a-lifetime shot!', '2003-02-24 00:14:53.000000', NULL, 1),
(222008, 13045, 4159, '<td valign="top">Very nice capture.  i would''ve personally liked it to have either more or less of his body, he seems chopped off prematurely the way it''s cropped now.</td>', 'Very nice capture.  i would''ve personally liked it to have either more or less of his body, he seems chopped off prematurely the way it''s cropped now.', '2003-02-24 00:15:28.000000', NULL, 1),
(222009, 13074, 6855, '<td valign="top">Cute photo, great lighting! For some reason it seems like it''s missing something???</td>', 'Cute photo, great lighting! For some reason it seems like it''s missing something???', '2003-02-24 00:15:57.000000', NULL, 1),
(222011, 13110, 4159, '<td valign="top">You caught a stunning sunset/rise here.  The colors are brilliant.  I''m not sure about the placement of the silhouette, though.</td>', 'You caught a stunning sunset/rise here.  The colors are brilliant.  I''m not sure about the placement of the silhouette, though.', '2003-02-24 00:17:02.000000', NULL, 1),
(222013, 12835, 6855, '<td valign="top">My husband says this one is the best! =) For the non-fishing person like myself, the background is a bit distracting, but it''s a gorgeous shot.</td>', 'My husband says this one is the best! =) For the non-fishing person like myself, the background is a bit distracting, but it''s a gorgeous shot.', '2003-02-24 00:17:17.000000', NULL, 1),
(222016, 12958, 6855, '<td valign="top">Yum!  The blueberries look a little dull to me for some reason, but I love the shot - it looks delicious!</td>', 'Yum!  The blueberries look a little dull to me for some reason, but I love the shot - it looks delicious!', '2003-02-24 00:18:19.000000', NULL, 1),
(222018, 12927, 4159, '<td valign="top">Nice macro, would''ve been very good in the Yellow challenge.  I can picture this hanging on the wall in a restaurant.  I think the water droplet on the left side second kernel from the left detracts, only because it breaks the (effective) curve.</td>', 'Nice macro, would''ve been very good in the Yellow challenge.  I can picture this hanging on the wall in a restaurant.  I think the water droplet on the left side second kernel from the left detracts, only because it breaks the (effective) curve.', '2003-02-24 00:18:40.000000', NULL, 1),
(222020, 13010, 6855, '<td valign="top">Great perspective, but for some reason, it seems like it''s missing something - I think it would have had more character if you would have caught the doors as well?  Cool building - where was it shot?</td>', 'Great perspective, but for some reason, it seems like it''s missing something - I think it would have had more character if you would have caught the doors as well?  Cool building - where was it shot?', '2003-02-24 00:19:23.000000', NULL, 1),
(222022, 13061, 4159, '<td valign="top">Pretty incredible amount of snow, not so incredible effect as a picture.  I think this would have been really nice if you''d upped the contrast a bit.</td>', 'Pretty incredible amount of snow, not so incredible effect as a picture.  I think this would have been really nice if you''d upped the contrast a bit.', '2003-02-24 00:19:32.000000', NULL, 1),
(222024, 12978, 6855, '<td valign="top">This is a great example of the rule of thirds.   I love the whole feel of this photo.  Awesome job!</td>', 'This is a great example of the rule of thirds.   I love the whole feel of this photo.  Awesome job!', '2003-02-24 00:20:19.000000', NULL, 1),
(222026, 12869, 4159, '<td valign="top">Focus is almost too shallow, but the lighting is effective and the fading lines are, too. <br/> <br/>Actually, I like the focus.  Nice shot.</td>', 'Focus is almost too shallow, but the lighting is effective and the fading lines are, too.  Actually, I like the focus.  Nice shot.', '2003-02-24 00:20:52.000000', NULL, 1),
(222028, 12849, 6855, '<td valign="top">Beautiful photo, but seems a little dark and gloomy for the challenge??? I love the detail and the tree is amazing!</td>', 'Beautiful photo, but seems a little dark and gloomy for the challenge??? I love the detail and the tree is amazing!', '2003-02-24 00:21:17.000000', NULL, 1),
(222032, 12869, 6855, '<td valign="top">The flash is a bit distracting in this photo, but otherwise, it looks great.</td>', 'The flash is a bit distracting in this photo, but otherwise, it looks great.', '2003-02-24 00:22:33.000000', NULL, 1),
(222033, 12998, 4159, '<td valign="top">There just doesn''t seem to be much that distinguishes this shot, as far as subject goes, and photographically, I think it''s a bit too bright.  Edges are also a bit fuzzy on a few of the jelly beans.</td>', 'There just doesn''t seem to be much that distinguishes this shot, as far as subject goes, and photographically, I think it''s a bit too bright.  Edges are also a bit fuzzy on a few of the jelly beans.', '2003-02-24 00:23:21.000000', NULL, 1),
(222034, 13096, 6855, '<td valign="top">This looks like a Victoria''s Secret  backdrop!  Definitely fits the challenge!</td>', 'This looks like a Victoria''s Secret  backdrop!  Definitely fits the challenge!', '2003-02-24 00:23:32.000000', NULL, 1),
(222036, 12938, 4159, '<td valign="top">Focus is a problem here, and I''m not sure that the subject would be all that interesting if it wasn''t.  I can, however, commend you on owning a pair of Converse All-Stars.</td>', 'Focus is a problem here, and I''m not sure that the subject would be all that interesting if it wasn''t.  I can, however, commend you on owning a pair of Converse All-Stars.', '2003-02-24 00:24:06.000000', NULL, 1),
(222038, 12854, 4159, '<td valign="top">Strikingly effective, almost three-dimensional.  NIce negative space.  Excellent shot.</td>', 'Strikingly effective, almost three-dimensional.  NIce negative space.  Excellent shot.', '2003-02-24 00:24:45.000000', NULL, 1),
(222040, 13092, 6855, '<td valign="top">As gorgeous as this is, it just doesn''t grab me for some reason. Maybe if the sky were bluer??? I still love it - it makes me long for summer!</td>', 'As gorgeous as this is, it just doesn''t grab me for some reason. Maybe if the sky were bluer??? I still love it - it makes me long for summer!', '2003-02-24 00:25:27.000000', NULL, 1),
(222043, 12866, 4159, '<td valign="top">The slant is throwing me here.  I like your choice of subject, but I think you should have tried some more agressive angles, like from below looking up, or from the side and below.</td>', 'The slant is throwing me here.  I like your choice of subject, but I think you should have tried some more agressive angles, like from below looking up, or from the side and below.', '2003-02-24 00:26:28.000000', NULL, 1),
(222044, 13054, 6855, '<td valign="top">This is very unique!  I''m anxious to see where this was shot!  Great use of the "rule of thirds".  The close-up snow seems a bit distracting, like it needs to be blurred to put more emphasis on the castle.  Very cool picture though!</td>', 'This is very unique!  I''m anxious to see where this was shot!  Great use of the "rule of thirds".  The close-up snow seems a bit distracting, like it needs to be blurred to put more emphasis on the castle.  Very cool picture though!', '2003-02-24 00:27:00.000000', NULL, 1),
(222046, 13101, 4159, '<td valign="top">I remember a photograph like this in the songtitles challenge.  The rose is a little too bright, and you might have tried angling the stem out from the mirror a bit.</td>', 'I remember a photograph like this in the songtitles challenge.  The rose is a little too bright, and you might have tried angling the stem out from the mirror a bit.', '2003-02-24 00:27:58.000000', NULL, 1),
(222047, 13006, 6855, '<td valign="top">Vegas, here we come!  Great photo, definitely meets the challenge. Seems like there should be a larger "focal" dice up front.</td>', 'Vegas, here we come!  Great photo, definitely meets the challenge. Seems like there should be a larger "focal" dice up front.', '2003-02-24 00:28:07.000000', NULL, 1),
(222048, 12976, 6855, '<td valign="top">beautiful</td>', 'beautiful', '2003-02-24 00:28:41.000000', NULL, 1),
(222049, 12922, 4159, '<td valign="top">The shadow is a major blemish on this interesting architecture.  I think, too, that a different angle would have rendered the subject even more interesting.  Nice find, though.</td>', 'The shadow is a major blemish on this interesting architecture.  I think, too, that a different angle would have rendered the subject even more interesting.  Nice find, though.', '2003-02-24 00:28:44.000000', NULL, 1),
(222050, 13096, 92, '<td valign="top">This is a great example of a stock photo ! = 10</td>', 'This is a great example of a stock photo ! = 10', '2003-02-24 00:29:03.000000', NULL, 1),
(222054, 13087, 6855, '<td valign="top">This is really an interesting photo, but for some reason I am missing a good focal point.  My eyes roam all over, without being drawn into one specific scene?? I will still rate it high, because it is a gorgeous photo.</td>', 'This is really an interesting photo, but for some reason I am missing a good focal point.  My eyes roam all over, without being drawn into one specific scene?? I will still rate it high, because it is a gorgeous photo.', '2003-02-24 00:30:12.000000', NULL, 1),
(222055, 12863, 4159, '<td valign="top">A little too much saturation here, the top of the tree appears to grow out of the horizon, and the reds are just too blindingly red.</td>', 'A little too much saturation here, the top of the tree appears to grow out of the horizon, and the reds are just too blindingly red.', '2003-02-24 00:30:43.000000', NULL, 1),
(222056, 13033, 92, '<td valign="top">Awesome photo ! Nice color and composition. Subject is great for stock photography ! = 10</td>', 'Awesome photo ! Nice color and composition. Subject is great for stock photography ! = 10', '2003-02-24 00:31:09.000000', NULL, 1),
(222057, 12854, 6855, '<td valign="top">Just  a little blurry, and maybe the lighting should be adjusted?  Still a fun topic and I really like the yellow background.</td>', 'Just  a little blurry, and maybe the lighting should be adjusted?  Still a fun topic and I really like the yellow background.', '2003-02-24 00:31:23.000000', NULL, 1),
(222058, 13082, 92, '<td valign="top">This has to be the best flag photo I''ve seen. The color and clarity are superb !!! = 10</td>', 'This has to be the best flag photo I''ve seen. The color and clarity are superb !!! = 10', '2003-02-24 00:31:46.000000', NULL, 1),
(222059, 13021, 4159, '<td valign="top">Nice pun in the title.  Even if this was photographed, though, it''s really more graphic art than photography in my opinion.  I still applaud your creativity.</td>', 'Nice pun in the title.  Even if this was photographed, though, it''s really more graphic art than photography in my opinion.  I still applaud your creativity.', '2003-02-24 00:32:04.000000', NULL, 1),
(222060, 13108, 6855, '<td valign="top">Very clever, but I think it would have had more "punch" with a spotlight on Texas and the rest of the states blurred slightly. I love the whole idea of it!</td>', 'Very clever, but I think it would have had more "punch" with a spotlight on Texas and the rest of the states blurred slightly. I love the whole idea of it!', '2003-02-24 00:32:25.000000', NULL, 1),
(222064, 13125, 4159, '<td valign="top">Charming eyes on that one.  The perspective with the bedsheets is also neat, but something about the lighting gives this a snapshot quality, which is a detractor.</td>', 'Charming eyes on that one.  The perspective with the bedsheets is also neat, but something about the lighting gives this a snapshot quality, which is a detractor.', '2003-02-24 00:33:21.000000', NULL, 1),
(222065, 12806, 6855, '<td valign="top">This is a fun idea, but the focus seems to be more on the gorgeous bowl than the candy.  I think this would have more impact in a plain bowl.  - Great idea though! You made me hungry!</td>', 'This is a fun idea, but the focus seems to be more on the gorgeous bowl than the candy.  I think this would have more impact in a plain bowl.  - Great idea though! You made me hungry!', '2003-02-24 00:33:34.000000', NULL, 1),
(222068, 13045, 92, '<td valign="top">Perfect light, color and clarity. The thirds use makes this a winner !!! Good luck ! = 10</td>', 'Perfect light, color and clarity. The thirds use makes this a winner !!! Good luck ! = 10', '2003-02-24 00:35:10.000000', NULL, 1),
(222069, 12867, 4159, '<td valign="top">Really like the stitches on this, they give your composition a lot of Umph.  I could definitely see this in a brochure, on a coach''s wall, etc., challenge is well met.</td>', 'Really like the stitches on this, they give your composition a lot of Umph.  I could definitely see this in a brochure, on a coach''s wall, etc., challenge is well met.', '2003-02-24 00:35:55.000000', NULL, 1),
(222070, 13071, 92, '<td valign="top">Really nice. The clarity, color and DOF are wonderful !</td>', 'Really nice. The clarity, color and DOF are wonderful !', '2003-02-24 00:36:12.000000', NULL, 1),
(222071, 12872, 5391, '<td valign="top">8 points for a good, clean stock-type shot + an extra point for the clever keywording title.  Made me laugh...  Clever.  9</td>', '8 points for a good, clean stock-type shot + an extra point for the clever keywording title.  Made me laugh...  Clever.  9', '2003-02-24 00:36:24.000000', NULL, 1),
(222073, 13098, 5391, '<td valign="top">Interesting image, isolated on the white background and marketable as stock.  Nice work.  8</td>', 'Interesting image, isolated on the white background and marketable as stock.  Nice work.  8', '2003-02-24 00:37:55.000000', NULL, 1),
(222075, 12924, 4159, '<td valign="top">Background is a bit distracting, but the bird is very well captured.  I kind of wish the colors were a bit more brilliant, not sure if you could have fiddled with it to make it that way.  Nice shot.</td>', 'Background is a bit distracting, but the bird is very well captured.  I kind of wish the colors were a bit more brilliant, not sure if you could have fiddled with it to make it that way.  Nice shot.', '2003-02-24 00:38:39.000000', NULL, 1),
(222077, 12934, 6855, '<td valign="top">Awesome photo through and through!  I know how hard it is to pose kids, and this is a great example on doing it right! I don''t see any flaws here at all.</td>', 'Awesome photo through and through!  I know how hard it is to pose kids, and this is a great example on doing it right! I don''t see any flaws here at all.', '2003-02-24 00:39:44.000000', NULL, 1),
(222078, 12872, 6855, '<td valign="top">Seems a little grainy, but I like the blue background.  I think I would have been more drawn to a blue base as well.</td>', 'Seems a little grainy, but I like the blue background.  I think I would have been more drawn to a blue base as well.', '2003-02-24 00:40:31.000000', NULL, 1),
(222081, 12985, 4159, '<td valign="top">Gorgeous colors.  This is hotel material.  Can''t find something to criticize, I''ll come back if I do, but that''s a good thing...</td>', 'Gorgeous colors.  This is hotel material.  Can''t find something to criticize, I''ll come back if I do, but that''s a good thing...', '2003-02-24 00:41:34.000000', NULL, 1),
(222082, 12882, 4159, '<td valign="top">Nice colors, but I can''t say much else.  That blemish in the upper right is distracting, and nothing really stands out here.</td>', 'Nice colors, but I can''t say much else.  That blemish in the upper right is distracting, and nothing really stands out here.', '2003-02-24 00:42:04.000000', NULL, 1),
(222084, 13000, 4159, '<td valign="top">Well, this is at least going in the top ten.  Nice focus, setup, composition, lighting (maglite?)...  Good shot.</td>', 'Well, this is at least going in the top ten.  Nice focus, setup, composition, lighting (maglite?)...  Good shot.', '2003-02-24 00:43:35.000000', NULL, 1),
(222086, 12958, 4159, '<td valign="top">Either overexposed or misfocused, several places are indistinct.  The composition is good, though, and the colors are nice.</td>', 'Either overexposed or misfocused, several places are indistinct.  The composition is good, though, and the colors are nice.', '2003-02-24 00:44:43.000000', NULL, 1),
(222090, 13010, 4159, '<td valign="top">It''s probably a trick of the resizing, but your windows have dotted lines.  Nice contrast, reminds me of Koyaanasqatsi, however that''s spelled.</td>', 'It''s probably a trick of the resizing, but your windows have dotted lines.  Nice contrast, reminds me of Koyaanasqatsi, however that''s spelled.', '2003-02-24 00:45:38.000000', NULL, 1),
(222097, 12806, 4159, '<td valign="top">Slightly uncentered.  Nice piece, but it doesn''t make a very effective picture, at least in the context of this photograph.</td>', 'Slightly uncentered.  Nice piece, but it doesn''t make a very effective picture, at least in the context of this photograph.', '2003-02-24 00:49:53.000000', NULL, 1),
(222099, 12862, 4159, '<td valign="top">The red really jumps out at me here, and that''s good.  I also like the shadow/reflection underneath the lips.</td>', 'The red really jumps out at me here, and that''s good.  I also like the shadow/reflection underneath the lips.', '2003-02-24 00:51:31.000000', NULL, 1),
(222100, 12980, 4159, '<td valign="top">I like the colors.  I wonder how this would look in sepia?  Nice composition, too.</td>', 'I like the colors.  I wonder how this would look in sepia?  Nice composition, too.', '2003-02-24 00:53:11.000000', NULL, 1),
(222101, 13082, 4159, '<td valign="top">This would have taken a ribbon over in the Cliches challenge, too.  Very nice work, photographically, and this might very easily hang in any schoolroom, governemnt office, or small business capitalizing on our new wave of patriotism.</td>', 'This would have taken a ribbon over in the Cliches challenge, too.  Very nice work, photographically, and this might very easily hang in any schoolroom, governemnt office, or small business capitalizing on our new wave of patriotism.', '2003-02-24 00:54:39.000000', NULL, 1),
(222102, 12904, 4159, '<td valign="top">Parts of this are a bit blurry.  Lighting is effective, though.</td>', 'Parts of this are a bit blurry.  Lighting is effective, though.', '2003-02-24 00:55:01.000000', NULL, 1),
(222142, 12969, 5585, '<td valign="top">Nice... fit the Challenge..</td>', 'Nice... fit the Challenge..', '2003-02-24 01:40:28.000000', NULL, 1),
(222143, 12888, 5585, '<td valign="top">Cool... fit the Challenge.... very creative</td>', 'Cool... fit the Challenge.... very creative', '2003-02-24 01:41:53.000000', NULL, 1),
(222209, 13122, 3540, '<td valign="top">Is this Miami?  This looks like a photojournalism shot.  A little dark for my tastes but not badly taken or anything.   I''m glad this missed us.</td>', 'Is this Miami?  This looks like a photojournalism shot.  A little dark for my tastes but not badly taken or anything.   I''m glad this missed us.', '2003-02-24 04:32:51.000000', NULL, 1),
(222210, 13015, 3540, '<td valign="top">Pretty good photo.  Lacking the crispness to make it a really good photo though.  I like the concept and the angle, just wondering where the sun is at this point.</td>', 'Pretty good photo.  Lacking the crispness to make it a really good photo though.  I like the concept and the angle, just wondering where the sun is at this point.', '2003-02-24 04:35:55.000000', NULL, 1),
(222212, 12872, 3540, '<td valign="top">Great subject and composition.  The tight center crop works very well.  The pic IMO looks like its been oversharpened or taken with a high ISO.  It also is a little overexposed for my tastes.  The blue is a nice color for the background.</td>', 'Great subject and composition.  The tight center crop works very well.  The pic IMO looks like its been oversharpened or taken with a high ISO.  It also is a little overexposed for my tastes.  The blue is a nice color for the background.', '2003-02-24 04:38:24.000000', NULL, 1),
(222217, 13000, 3540, '<td valign="top">I like the lighting and the shadows.  Good choice of background colors as well.</td>', 'I like the lighting and the shadows.  Good choice of background colors as well.', '2003-02-24 05:12:41.000000', NULL, 1),
(222218, 12953, 3540, '<td valign="top">This looks like it might fit in a sunflower themed room.  My friend used to have one at her house that this would fit right into.  The biggest problem being that its'' not terribly focused.  Other than that is has nice colors and is well framed with good background</td>', 'This looks like it might fit in a sunflower themed room.  My friend used to have one at her house that this would fit right into.  The biggest problem being that its'' not terribly focused.  Other than that is has nice colors and is well framed with good background', '2003-02-24 05:19:11.000000', NULL, 1),
(222219, 12998, 3540, '<td valign="top">Nice bright colors on this one.   Lots of highlights on the beans, I don''t like how they are sort of oblong.  I would think a hightlight on something like this would be small and round.  Nice shot</td>', 'Nice bright colors on this one.   Lots of highlights on the beans, I don''t like how they are sort of oblong.  I would think a hightlight on something like this would be small and round.  Nice shot', '2003-02-24 05:21:30.000000', NULL, 1),
(222220, 12940, 3540, '<td valign="top">Looks like sunflare hell right dead center of the picture.  Nice tree silhouettes though</td>', 'Looks like sunflare hell right dead center of the picture.  Nice tree silhouettes though', '2003-02-24 05:22:35.000000', NULL, 1),
(222221, 12924, 3540, '<td valign="top">I don''t like the fence in the background but the bird is magnificent.  Very well taken.  A pinch more exposure might''ve done you good if it didn''t was the background out</td>', 'I don''t like the fence in the background but the bird is magnificent.  Very well taken.  A pinch more exposure might''ve done you good if it didn''t was the background out', '2003-02-24 05:24:49.000000', NULL, 1),
(222222, 13024, 3540, '<td valign="top">I''m curious to know what made you cut the picture off on the left side and include this pole that seems unattached on the right.  The picture isn''t too bad, looks like you might''ve lost some picture quality in compression judging by the lines being not so fluid.  Overall not too bad, but I think a better crop would''ve served you well</td>', 'I''m curious to know what made you cut the picture off on the left side and include this pole that seems unattached on the right.  The picture isn''t too bad, looks like you might''ve lost some picture quality in compression judging by the lines being not so fluid.  Overall not too bad, but I think a better crop would''ve served you well', '2003-02-24 05:27:10.000000', NULL, 1),
(222225, 12987, 3540, '<td valign="top">She doesn''t look to happy to be there.  Neat lighting and I like the chair effect.  The light looks a little bright as its washing her hair out.  The crop could be better IMO including the whole chair but isn''t necessary.</td>', 'She doesn''t look to happy to be there.  Neat lighting and I like the chair effect.  The light looks a little bright as its washing her hair out.  The crop could be better IMO including the whole chair but isn''t necessary.', '2003-02-24 05:31:36.000000', NULL, 1),
(222229, 12971, 3540, '<td valign="top">Great color, framing, and as sharp as any picture I''ve seen on dpc.  I''m wondering what camera this is, because I think I know :)  Great job</td>', 'Great color, framing, and as sharp as any picture I''ve seen on dpc.  I''m wondering what camera this is, because I think I know :)  Great job', '2003-02-24 05:37:35.000000', NULL, 1),
(222267, 13021, 2344, '<td valign="top">You''re such a weirdo Jacko! Nice clips!</td>', 'You''re such a weirdo Jacko! Nice clips!', '2003-02-24 07:18:20.000000', NULL, 1),
(222269, 13105, 2344, '<td valign="top">The idea is good but the technics need working on. The left side of the face is too blown out and the focus is a little too far off to be considered soft. Keep at it!</td>', 'The idea is good but the technics need working on. The left side of the face is too blown out and the focus is a little too far off to be considered soft. Keep at it!', '2003-02-24 07:20:01.000000', NULL, 1),
(222275, 13109, 6025, '<td valign="top">Very nice and artistic image, but as far as stock photography goes, I think you are getting a little bit too abstract. (7)</td>', 'Very nice and artistic image, but as far as stock photography goes, I think you are getting a little bit too abstract. (7)', '2003-02-24 07:39:31.000000', NULL, 1),
(222278, 13010, 6025, '<td valign="top">A good image, but the digital noise (compression errors?) really pulls this one down I am afraid. (4)</td>', 'A good image, but the digital noise (compression errors?) really pulls this one down I am afraid. (4)', '2003-02-24 07:40:27.000000', NULL, 1),
(222281, 12888, 6025, '<td valign="top">An interesting image indeed. For perfection, I would have tried to remove the text off of the side of the bulb, though... I can think of quite a lot of stock photography usage where "made in france" would be a problem. (7)</td>', 'An interesting image indeed. For perfection, I would have tried to remove the text off of the side of the bulb, though... I can think of quite a lot of stock photography usage where "made in france" would be a problem. (7)', '2003-02-24 07:42:02.000000', NULL, 1),
(222282, 12942, 6025, '<td valign="top">The image seems fuzzy - try to use a smaller aperture, and make sure that teh "amtrak" logo is 109% in focus. Good idea, however (5)</td>', 'The image seems fuzzy - try to use a smaller aperture, and make sure that teh "amtrak" logo is 109% in focus. Good idea, however (5)', '2003-02-24 07:43:01.000000', NULL, 1),
(222284, 13082, 6025, '<td valign="top">Last time I checked, the stars on the american flag are white.. DOn''t know why it does not look that way on this image, but it certainly pulls down the overall of this otherwise very good picture (6)</td>', 'Last time I checked, the stars on the american flag are white.. DOn''t know why it does not look that way on this image, but it certainly pulls down the overall of this otherwise very good picture (6)', '2003-02-24 07:44:00.000000', NULL, 1),
(222286, 13101, 6025, '<td valign="top">Try to be a little bit more creative with your lighting, and make sure you get a wider tonal range than this. Also, using a longer shutter time and smaller aperture might have helped you to get it all sharp. Also try to use a good level of USM. (4)</td>', 'Try to be a little bit more creative with your lighting, and make sure you get a wider tonal range than this. Also, using a longer shutter time and smaller aperture might have helped you to get it all sharp. Also try to use a good level of USM. (4)', '2003-02-24 07:45:27.000000', NULL, 1),
(222287, 13043, 6025, '<td valign="top">A good image, but the reflection on the middle of the globe makes it look as if you used a flash. Flashes are bad. Use a diffused light source, preferrably from one or more of the sides, to give it a rounder feel. Nice shot and subtle sepiatoning though. (8)</td>', 'A good image, but the reflection on the middle of the globe makes it look as if you used a flash. Flashes are bad. Use a diffused light source, preferrably from one or more of the sides, to give it a rounder feel. Nice shot and subtle sepiatoning though. (8)', '2003-02-24 07:46:44.000000', NULL, 1),
(222289, 13120, 6025, '<td valign="top">An good (albeit not very original) idea that is ruined by the heavy over exposure. Try again! (4)</td>', 'An good (albeit not very original) idea that is ruined by the heavy over exposure. Try again! (4)', '2003-02-24 07:49:08.000000', NULL, 1),
(222291, 12927, 6025, '<td valign="top">the corner things look gorgeous, but the centre looks like brain stew. To be honest, I would never consider putting this on print because of that. Of course, just my subjective opinion. (5)</td>', 'the corner things look gorgeous, but the centre looks like brain stew. To be honest, I would never consider putting this on print because of that. Of course, just my subjective opinion. (5)', '2003-02-24 07:52:44.000000', NULL, 1),
(222293, 13025, 6025, '<td valign="top">Are those snowflakes or water on your lens? Sorry, but those two drops really put me off this image. A good idea, but nobody would buy the image - they would instead send one of their own photographers to the nearest petrol station. (4)</td>', 'Are those snowflakes or water on your lens? Sorry, but those two drops really put me off this image. A good idea, but nobody would buy the image - they would instead send one of their own photographers to the nearest petrol station. (4)', '2003-02-24 07:57:43.000000', NULL, 1),
(222305, 12987, 5728, '<td valign="top">Cool! I love this photo, one of my favourites this week.  The light playing in her hair is amazing. The crop is great, it just goes to show you that you don''t always have to crop a person at the waist or knees right. I hope you gave her some candy for modelling so well, or you ate it yourself didn''t you! 9 from me if you gave her the candy :-)</td>', 'Cool! I love this photo, one of my favourites this week.  The light playing in her hair is amazing. The crop is great, it just goes to show you that you don''t always have to crop a person at the waist or knees right. I hope you gave her some candy for modelling so well, or you ate it yourself didn''t you! 9 from me if you gave her the candy :-)', '2003-02-24 08:18:01.000000', NULL, 1),
(222319, 12872, 2170, '<td valign="top">LOL.  I''m voting on this one first because your title indicates that you''re someone who spends a LOT of time on corbis (like me).  It really did make me laugh outloud!<br/> <br/>Oh, yeah...and good shot too.  Very simple and I like the blue tint.</td>', 'LOL.  I''m voting on this one first because your title indicates that you''re someone who spends a LOT of time on corbis (like me).  It really did make me laugh outloud! Oh, yeah...and good shot too.  Very simple and I like the blue tint.', '2003-02-24 08:40:06.000000', NULL, 1),
(222333, 12872, 6100, '<td valign="top">I like the blue color and your overall lighting. You''ve not only captured the challenge in your photo, you''ve even followed through with the title! Beautiful job.</td>', 'I like the blue color and your overall lighting. You''ve not only captured the challenge in your photo, you''ve even followed through with the title! Beautiful job.', '2003-02-24 09:03:53.000000', NULL, 1),
(222335, 13108, 6100, '<td valign="top">Nice job of the selective focus to emphasize a particular American state. The use of the black background leaves room for a caption if necessary and leaves room if an editor wants to crop this to a vertical without destroying the picture.</td>', 'Nice job of the selective focus to emphasize a particular American state. The use of the black background leaves room for a caption if necessary and leaves room if an editor wants to crop this to a vertical without destroying the picture.', '2003-02-24 09:07:06.000000', NULL, 1),
(222337, 12940, 6100, '<td valign="top">About the only thing I don''t like about your picture is the lens flare in the middle. Other than that, I think you''ve captured a beautiful scene.</td>', 'About the only thing I don''t like about your picture is the lens flare in the middle. Other than that, I think you''ve captured a beautiful scene.', '2003-02-24 09:08:21.000000', NULL, 1),
(222352, 12927, 1569, '<td valign="top">The wet look th the cob center is kind of gross.Turning the ear so the center wasn''t as prominent and showed more kernels may have worked better.</td>', 'The wet look th the cob center is kind of gross.Turning the ear so the center wasn''t as prominent and showed more kernels may have worked better.', '2003-02-24 09:16:43.000000', NULL, 1),
