(223476, 12854, 3575, '<td valign="top">Great shot, gorgeous background! I like that the only sharp part is the part that counts.</td>', 'Great shot, gorgeous background! I like that the only sharp part is the part that counts.', '2003-02-24 20:51:34.000000', NULL, 1),
(223483, 13117, 3575, '<td valign="top">Amazing sky! I would like to see the boats a lilttle bit sharper but it could just be the result of downsizing for submission. The bird is a nice addition to the photo.</td>', 'Amazing sky! I would like to see the boats a lilttle bit sharper but it could just be the result of downsizing for submission. The bird is a nice addition to the photo.', '2003-02-24 20:52:56.000000', NULL, 1),
