INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(223820, 13010, 3540, '<td valign="top">Looks like the window lines in both directions are suffering from some compression ailments.  Cool buildings, did you take them not square to the horizon on purpose?</td>', 'Looks like the window lines in both directions are suffering from some compression ailments.  Cool buildings, did you take them not square to the horizon on purpose?', '2003-02-25 04:28:23.000000', NULL, 1),
(223821, 13038, 3540, '<td valign="top">This photo needs to be tilted one or two degrees ccw.  I like the tree in the center, but I don''t like how bright it is.  Overall good shot though</td>', 'This photo needs to be tilted one or two degrees ccw.  I like the tree in the center, but I don''t like how bright it is.  Overall good shot though', '2003-02-25 04:33:27.000000', NULL, 1),
(223823, 13054, 3540, '<td valign="top">The steps or whatever the border on the left would frame the picture well if they didn''t come into the frame quite so far.  The snow is gorgeous.  Cool little tower thing as well.</td>', 'The steps or whatever the border on the left would frame the picture well if they didn''t come into the frame quite so far.  The snow is gorgeous.  Cool little tower thing as well.', '2003-02-25 04:36:09.000000', NULL, 1),
(223824, 12880, 3540, '<td valign="top">If Ansel shot this the DOF would have been much greater.  The colors are kind of dreary, even for B&amp;W.  Maybe it needs a little more contrast</td>', 'If Ansel shot this the DOF would have been much greater.  The colors are kind of dreary, even for B&W.  Maybe it needs a little more contrast', '2003-02-25 04:38:41.000000', NULL, 1),
(223826, 13090, 3540, '<td valign="top">Exposure is way too long here.  The lack of clarity of the people is really not helping this photo.  There doesn''t really seem to be much market activity here anyway.</td>', 'Exposure is way too long here.  The lack of clarity of the people is really not helping this photo.  There doesn''t really seem to be much market activity here anyway.', '2003-02-25 04:45:23.000000', NULL, 1),
(223827, 12882, 3540, '<td valign="top">The bright light in the middle on the left side of the centerpiece is very, very distracting IMO. I love the colors of this, but I think they could''ve used a little help from PS with a bit more saturation to make them a bit more vivid.</td>', 'The bright light in the middle on the left side of the centerpiece is very, very distracting IMO. I love the colors of this, but I think they could''ve used a little help from PS with a bit more saturation to make them a bit more vivid.', '2003-02-25 04:47:30.000000', NULL, 1),
(223829, 12980, 3540, '<td valign="top">Awesome wall.  I really like the contrasting colors of the shutters with the wall.  The wall is very cool as well with the unique colors and strange patterns.  Great shot.</td>', 'Awesome wall.  I really like the contrasting colors of the shutters with the wall.  The wall is very cool as well with the unique colors and strange patterns.  Great shot.', '2003-02-25 04:50:03.000000', NULL, 1),
(223830, 13006, 3540, '<td valign="top">This pic would''ve been much better with the right lighting.  You have a lot of cool translucent dice but really could''ve taken advantage with something lighting them up properly, without the whole picture being so bright.  Interesting idea for a shot though.  Someone is a gamer looks like.</td>', 'This pic would''ve been much better with the right lighting.  You have a lot of cool translucent dice but really could''ve taken advantage with something lighting them up properly, without the whole picture being so bright.  Interesting idea for a shot though.  Someone is a gamer looks like.', '2003-02-25 04:52:42.000000', NULL, 1),
(223832, 12976, 3540, '<td valign="top">Best of the stock photos I''ve seen so far, hands down.  Great shot.  Wonderful capture. =10</td>', 'Best of the stock photos I''ve seen so far, hands down.  Great shot.  Wonderful capture. =10', '2003-02-25 04:59:42.000000', NULL, 1),
(223834, 13125, 3540, '<td valign="top">Baby looks a little blotchy.... sure she''s not allergic to your Fabric Softener?  Cute pic but it doesn''t do much for me in the way of Stock Photography</td>', 'Baby looks a little blotchy.... sure she''s not allergic to your Fabric Softener?  Cute pic but it doesn''t do much for me in the way of Stock Photography', '2003-02-25 05:04:02.000000', NULL, 1),
(223837, 13123, 3540, '<td valign="top">Very nice shot.  Love the silhouettes of the hill an trees.  Water is very calm.  Great capture of the clouds and sun.</td>', 'Very nice shot.  Love the silhouettes of the hill an trees.  Water is very calm.  Great capture of the clouds and sun.', '2003-02-25 05:06:56.000000', NULL, 1),
(223838, 12866, 3540, '<td valign="top">If this pic wasn''t leaning so hard to the left it would definitely be a 10.  THis is really gorgeous.  Well framed in by the trees and everything.  awesome.  Settle for 9?</td>', 'If this pic wasn''t leaning so hard to the left it would definitely be a 10.  THis is really gorgeous.  Well framed in by the trees and everything.  awesome.  Settle for 9?', '2003-02-25 05:08:30.000000', NULL, 1),
(223840, 13071, 3540, '<td valign="top">I don''t like the pinecones that underexposed.  They lack color, not that they''re jumping with vivid color to begin with, but I think they should look at least like wood.  Great DOF on this shot.</td>', 'I don''t like the pinecones that underexposed.  They lack color, not that they''re jumping with vivid color to begin with, but I think they should look at least like wood.  Great DOF on this shot.', '2003-02-25 05:10:10.000000', NULL, 1),
(223841, 12849, 1829, '<td valign="top">Now this has to win hands down.  Excellent dramatic image.  The b&amp;w portrays the dramatic feel as to the haunting looking tree.  Excellent composition and clarity.  10 from me.</td>', 'Now this has to win hands down.  Excellent dramatic image.  The b&w portrays the dramatic feel as to the haunting looking tree.  Excellent composition and clarity.  10 from me.', '2003-02-25 05:11:50.000000', NULL, 1),
(223842, 12914, 3540, '<td valign="top">Cool building.  unbelievable that they''d build something like this on a dock.  Hope it never freezes there:)  Nice rich colors of the wood.  I think it would be a little better if it were just a pinch sharper and clearer.</td>', 'Cool building.  unbelievable that they''d build something like this on a dock.  Hope it never freezes there:)  Nice rich colors of the wood.  I think it would be a little better if it were just a pinch sharper and clearer.', '2003-02-25 05:12:02.000000', NULL, 1),
(223843, 13123, 1829, '<td valign="top">A beautiful tranquil setting.  I particualrly love the way you have captured the light coming out from the clouds and reflecting off the water.  Excellent composition and clarity.  Well done and gl.</td>', 'A beautiful tranquil setting.  I particualrly love the way you have captured the light coming out from the clouds and reflecting off the water.  Excellent composition and clarity.  Well done and gl.', '2003-02-25 05:12:50.000000', NULL, 1),
(223844, 12849, 3540, '<td valign="top">Awesome image.  Really breathtaking.  Great capture of the sky and behind this tree makes it a 10 in my book.  Awesome!!</td>', 'Awesome image.  Really breathtaking.  Great capture of the sky and behind this tree makes it a 10 in my book.  Awesome!!', '2003-02-25 05:14:13.000000', NULL, 1),
(223845, 13093, 1829, '<td valign="top">Beautifully composed.  I lke the colour in which you chose - gives an ''olden'' type of feeling.  The tree also adds a nice touch over the sky as well.  Kind of breaks the boringness of the sky with patterns from the branches overhanging it.  Excellent photo.  GL.</td>', 'Beautifully composed.  I lke the colour in which you chose - gives an ''olden'' type of feeling.  The tree also adds a nice touch over the sky as well.  Kind of breaks the boringness of the sky with patterns from the branches overhanging it.  Excellent photo.  GL.', '2003-02-25 05:15:02.000000', NULL, 1),
(223846, 13120, 3540, '<td valign="top">I think the child''s head should be taking up a little more of the frame.  There is too much open area here.  Great concept though.  The lighting is a little harsh for my tastes.  This is a great pic though.</td>', 'I think the child''s head should be taking up a little more of the frame.  There is too much open area here.  Great concept though.  The lighting is a little harsh for my tastes.  This is a great pic though.', '2003-02-25 05:17:54.000000', NULL, 1),
(223847, 13059, 1829, '<td valign="top">A well composed image with that wonderful blue sky colour.  I really like the subject in which you chose (don''t see many castles where I''m from).  I also like the shadows in a streamline fashion coming off the snow.  The tree also adds interest.  Excellent photo for the ''stock'' challenge.  GL.</td>', 'A well composed image with that wonderful blue sky colour.  I really like the subject in which you chose (don''t see many castles where I''m from).  I also like the shadows in a streamline fashion coming off the snow.  The tree also adds interest.  Excellent photo for the ''stock'' challenge.  GL.', '2003-02-25 05:18:12.000000', NULL, 1),
(223848, 13082, 3540, '<td valign="top">Tremendous colors.  I wish the stars were on this side so they''d be white.  THe waves in the flag are great though.  I like the little bit of background showing.  Gives a little perspective so to speak.  Great job</td>', 'Tremendous colors.  I wish the stars were on this side so they''d be white.  THe waves in the flag are great though.  I like the little bit of background showing.  Gives a little perspective so to speak.  Great job', '2003-02-25 05:19:49.000000', NULL, 1),
(223849, 12854, 1829, '<td valign="top">Lighting in your image is fantastic.  I love the choice of subject and also the dof is awesome.  Excellent work and GL.</td>', 'Lighting in your image is fantastic.  I love the choice of subject and also the dof is awesome.  Excellent work and GL.', '2003-02-25 05:21:03.000000', NULL, 1),
(223852, 13045, 1829, '<td valign="top">LOL - love the title, it made me laugh.  Clarity and subject is brilliant.  I also love the dof.  Not too much and not too little, dof is just right.  Excellent work and GL.</td>', 'LOL - love the title, it made me laugh.  Clarity and subject is brilliant.  I also love the dof.  Not too much and not too little, dof is just right.  Excellent work and GL.', '2003-02-25 05:23:26.000000', NULL, 1),
(223854, 13117, 1829, '<td valign="top">An excellent image.  I''m familiar with clouds like those (we have a lot like these where I''m from).  I love how you have captured this beautiful scenery.  Certainly a well defined stock photo.  Excellent job and GL.</td>', 'An excellent image.  I''m familiar with clouds like those (we have a lot like these where I''m from).  I love how you have captured this beautiful scenery.  Certainly a well defined stock photo.  Excellent job and GL.', '2003-02-25 05:28:33.000000', NULL, 1),
(223856, 13033, 3540, '<td valign="top">Great subject, great lighting, great background.  Top ten, maybe even top 3.  Awesome!!</td>', 'Great subject, great lighting, great background.  Top ten, maybe even top 3.  Awesome!!', '2003-02-25 05:32:26.000000', NULL, 1),
(223858, 13086, 3599, '<td valign="top">I like the movement and framing of this photo.</td>', 'I like the movement and framing of this photo.', '2003-02-25 05:36:30.000000', NULL, 1),
(223859, 13041, 3540, '<td valign="top">Almost really good.  Photo quality is really really good.  The only thing I have to say about this is, and don''t take this the wrong way, straighter teeth would''ve made this image a 9 or 10.</td>', 'Almost really good.  Photo quality is really really good.  The only thing I have to say about this is, and don''t take this the wrong way, straighter teeth would''ve made this image a 9 or 10.', '2003-02-25 05:36:41.000000', NULL, 1),
(223860, 13105, 6100, '<td valign="top">As your title suggests, the right side could be used for text. However, one thing photo buyers are looking for is sharp images and this one isn''t.</td>', 'As your title suggests, the right side could be used for text. However, one thing photo buyers are looking for is sharp images and this one isn''t.', '2003-02-25 05:36:58.000000', NULL, 1),
(223861, 12987, 3599, '<td valign="top">Very nice, I could see this one in a picture frame on the store shelf.  Good work.</td>', 'Very nice, I could see this one in a picture frame on the store shelf.  Good work.', '2003-02-25 05:38:06.000000', NULL, 1),
(223862, 13105, 3599, '<td valign="top">I like the border.  I like the soft focus because you had an ad in mind when you took it.  The product or the text on the right side would have to be sharp and in focus.  Good luck in the challenge.</td>', 'I like the border.  I like the soft focus because you had an ad in mind when you took it.  The product or the text on the right side would have to be sharp and in focus.  Good luck in the challenge.', '2003-02-25 05:41:02.000000', NULL, 1),
(223863, 13010, 6100, '<td valign="top">Generally, a nicely exposed shot. The photo could, indeed, be used in an annual report but probably only if it''s for a company which occupies this building. In stock photography, you want an image which will sell over and over again and I''m not sure how this one would. (I can''t see much call for generic building shots.)</td>', 'Generally, a nicely exposed shot. The photo could, indeed, be used in an annual report but probably only if it''s for a company which occupies this building. In stock photography, you want an image which will sell over and over again and I''m not sure how this one would. (I can''t see much call for generic building shots.)', '2003-02-25 05:45:09.000000', NULL, 1),
(223864, 12824, 3585, '<td valign="top">very nice and unusual image, much to interesting to end up as sucessfull stock. 9</td>', 'very nice and unusual image, much to interesting to end up as sucessfull stock. 9', '2003-02-25 05:46:56.000000', NULL, 1),
(223867, 13087, 6100, '<td valign="top">Nice skyline. Clouds in the sky would add depth to this photo. You might also try shooting a similar shot at twilight or even at night. Skylines of major cities can be a major part of a stock photographer''s money-making portfolio so you''ve chosen a good subject. I''m not too keen on the "steel cage" at the left side of the photo. It breaks the view of the city and distracts the eye. I would try a slightly different viewpoint. The color of the light on the buildings is very nice.</td>', 'Nice skyline. Clouds in the sky would add depth to this photo. You might also try shooting a similar shot at twilight or even at night. Skylines of major cities can be a major part of a stock photographer''s money-making portfolio so you''ve chosen a good subject. I''m not too keen on the "steel cage" at the left side of the photo. It breaks the view of the city and distracts the eye. I would try a slightly different viewpoint. The color of the light on the buildings is very nice.', '2003-02-25 05:54:00.000000', NULL, 1),
